DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.prepare_service_returns(uuid,boolean)'::regprocedure) INTO def; def:=replace(def,'''! 💛 Já faz ''||greatest((now() AT TIME ZONE ''America/Sao_Paulo'')::date-t.last_visit,0)||'' dias desde nosso cuidado com ''||t.service||''. Que tal reservar um tempinho para você? Vamos consultar um horário com carinho? ''','''! 💛 Seu cuidado com ''||t.service||'' tem retorno previsto a cada ''||t.interval_days||'' dias. Que tal reservar um tempinho para você? Vamos consultar um horário com carinho? '''); def:=replace(def,'ON CONFLICT(dedupe_key) DO NOTHING;', 'ON CONFLICT(dedupe_key) DO UPDATE SET status=''aguardando_conexao_whatsapp'',agendado_para=excluded.agendado_para,mensagem=excluded.mensagem,error='''' WHERE _manual AND public.fila_mensagens_ia.status IN (''aguardando_conexao_whatsapp'',''cancelado'') AND public.fila_mensagens_ia.agendado_para<now()-interval ''15 minutes'' AND public.fila_mensagens_ia.sent_at IS NULL;'); EXECUTE def; END $$;